@pytest.mark.parametrize("industry", ["other", "accounting_bookkeeping"]) def test_capture_v4_actual_worker_chromium_private_owner_delivery( capture_context, enabled, tmp_path, industry, client, settings, monkeypatch ): user, org = capture_context org.industry = industry org.save(update_fields=["industry"]) settings.CORE_PROPOSAL_ADMISSION_ENABLED = True settings.DECISION_DESK_ENABLED = True CoreProposalAdmissionGate.objects.update_or_create(id=1, defaults={"enabled": True}) DecisionDeskGate.objects.update_or_create(id=1, defaults={"enabled": True}) snapshot = admit(capture_context, preview(capture_context)) revision = issue_capture_proposals( organization_id=org.id, actor_id=user.id, snapshot_id=snapshot.id, using="app_runtime", ) prior = None event_ids = [] for kind, state in (("disposition", "act"), ("execution", "completion_recorded")): prior = record_capture_decision( organization_id=org.id, actor_id=user.id, revision_id=revision.id, proposal_id=UUID(revision.cards[0]["proposal_id"]), proposal_sha256=revision.cards[0]["sha256"], card_index=0, event_kind=kind, state=state, responsible_label="Named responsible owner", expected_previous_event=prior, notes="Owner statement is not verified resolution.", links=["https://example.invalid/reference"], using="app_runtime", ) event_ids.append(prior) cycle = open_cycle( organization_id=org.id, actor_id=user.id, input_snapshot_id=snapshot.id, using="app_runtime", ) pack = freeze_cycle( cycle_id=cycle.id, organization_id=org.id, actor_id=user.id, expected_revision=1, using="app_runtime", ) assert pack.manifest["schema"] == "stewardence.review_pack.v4" assert len(pack.manifest["selected_proposals"]) == len(revision.cards) assert {item["event_id"] for item in pack.manifest["selected_decisions"]} == { str(value) for value in event_ids } assert all( DecisionEvent.objects.get(id=value).payload["resolution_verified"] is False for value in event_ids ) staged = request_pack_artifact( pack_id=pack.id, organization_id=org.id, actor_id=user.id, promote_baseline=False, using="app_runtime", ) BackgroundJob.objects.filter(id=staged.job_id).update(priority=-100) with transaction.atomic(using="worker_runtime"): job = claim_next_job("capture-review-qualification", using="worker_runtime") assert job is not None and job.id == staged.job_id with ( tenant_transaction(org.id, using="worker_runtime"), connections["worker_runtime"].cursor() as cursor, ): cursor.execute("SELECT current_user,current_setting('transaction_isolation')") assert cursor.fetchone() == ("agentledger_worker", "read committed") renderer = ActualRenderer(tmp_path / "render") delegate = ReportGenerationHandler( renderer=renderer, storage=LocalPrivateReportStorage(tmp_path / "private"), using="worker_runtime", ) handler = ReviewReportGenerationHandler( delegate, worker_id="capture-review-qualification" ) execute_claimed_job( JobExecution(job=job, worker_id="capture-review-qualification"), handler, using="worker_runtime", ) assert renderer.context["context_version"] == "AL-REVIEW-PACK-CONTEXT-3" assert renderer.context["projection"]["manifest_sha256"] == pack.sha256 text = " ".join( " ".join( page.extract_text() or "" for page in PdfReader(BytesIO(renderer.pdf)).pages ).split() ) assert "Risk: not assessed" in text and "Benefit model: not supplied" in text assert "Generic exposure review" in text and "Low" not in text assert "disposition: act" in text and "execution: completion_recorded" in text assert "Original outcome: UNKNOWN" in text completion = PackCompletion.objects.get(request=staged) assert completion.payload["verification"] == "trusted_handler_storage_readback" assert completion.payload["baseline_outcome"] == "not_requested" assert completion.payload["manifest_sha256"] == pack.sha256 assert completion.artifact.sha256 == completion.payload["artifact_sha256"] assert not BaselineHead.objects.filter(organization=org).exists() assert ReviewCycle.objects.get(id=cycle.id).state == "COMPLETED" assert BackgroundJob.objects.get(id=job.id).status == "completed" settings.ALLOWED_HOSTS = ["testserver"] client.force_login(user) session = client.session session["active_organization_id"] = str(org.id) session.save()
